excels.excel:

EXPORT WITH SHEET="分组销售聚合", HEADER=true,
    MAPPING={"a":"大区","b":"门店","c":"一季度","d":"二季度","e":"三季度","f":"四季度"},
    FORMAT={"c":"#,##0","d":"#,##0","e":"#,##0","f":"#,##0"},
    STYLE={
        ROW 1:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:center,verticalAlignment:center}
    },
    MERGE:{
        RANGE A2:A3 WITH MERGE_WITH_FIRST,
        RANGE A4:A5 WITH MERGE_WITH_FIRST,
        RANGE A6:A7 WITH MERGE_WITH_FIRST
    }
